import networkx as nx
G = nx.Graph()
for i in range(25):
    G.add_node(i)
for i in range(25):
    for j in range(i+1, 25):
        if len(list(G.neighbors(i))) < 5 and len(list(G.neighbors(j))) < 5:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 5 or len(list(G.neighbors(j))) == 5:
                break
if min(degree for node, degree in G.degree()) >= 3 and max(degree for node, degree in G.degree()) <= 5 and nx.girth(G) >= 7:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
